head.script:
scwin.callCount = 0;
scwin.focusTimer = null;

// 스크립트로 DataList Row 1 에 무효 날짜 설정
scwin.btn_setCellData_onclick = function (e) {
    dlt_A.setCellData(1, "cal", "20261345");
    scwin.setReturnValue("setCellData : Row 1 저장값 " + dlt_A.getCellData(1, "cal"));
};

// 편집 진입
scwin.grd_A_onbeforeedit = function (rowIndex, colIndex, value) {
    scwin.setReturnValue("편집 진입 : Row " + rowIndex + " (값 " + value + ")");
};

// 편집 종료 (DataList 반영 후)
scwin.grd_A_onafteredit = function (rowIndex, colIndex, value) {
    scwin.setReturnValue("편집 종료 : Row " + rowIndex + " 저장값 " + dlt_A.getCellData(rowIndex, "cal"));
};

// calendar Column 의 invalidMessageFunc
scwin.grd_A_cal_invalidMessageFunc = function () {
    scwin.callCount++;
    let inputEl = document.getElementById(this.callerId + "_input");
    let rowIndex = grd_A.getFocusedRowIndex();
    scwin.setReturnValue("invalidMessageFunc 호출 " + scwin.callCount + " : Row " + rowIndex
        + " 편집창 값 " + (inputEl ? inputEl.value : ""));
    scwin.reportFocus(inputEl, rowIndex);
};

// 호출이 끝난 뒤 편집 상태(포커스 위치)·저장값 1줄 출력
scwin.reportFocus = function (inputEl, rowIndex) {
    if (scwin.focusTimer) {
        clearTimeout(scwin.focusTimer);
    }
    scwin.focusTimer = setTimeout(function () {
        scwin.focusTimer = null;
        let editing = (inputEl !== null && document.activeElement === inputEl);
        scwin.setReturnValue("  → " + (editing ? "편집 중 (포커스 편집창)" : "편집창 밖")
            + " / 편집창 값 " + (inputEl ? inputEl.value : "") + " / Row " + rowIndex + " 저장값 " + dlt_A.getCellData(rowIndex, "cal"));
    }, 300);
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
    scwin.callCount = 0;
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
